import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d,i as h,S as m}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"低秩分解","description":"","frontmatter":{"title":"低秩分解","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/low-rank-factorization.md","filePath":"llm/low-rank-factorization.md","lastUpdated":1789023840000}'),A={name:"llm/low-rank-factorization.md"};function p(E,a,_,c,u,S){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="低秩分解" tabindex="-1">低秩分解 <a class="header-anchor" href="#低秩分解" aria-label="Permalink to &quot;低秩分解&quot;">​</a></h1><div class="epigraph"><p>把已经训好的 $W$ 写成 $UV$，推理变成两次瘦矩阵乘。这压缩的是 $W_0$ 的秩，不是 LoRA 那种只学 $\\Delta W$ 的增量。</p><footer>—— Hsu et al., Language Model Compression with Weighted Low-Rank Factorization, ICLR 2022；对照 Eckart–Young 的截断 SVD</footer></div><p><a href="/llm/attention-head-pruning">上一课</a> 删的是整头。本课形状还在，秩下降：每层 \\(W\\approx UV\\)，参数从 \\(d_{\\mathrm{out}}d_{\\mathrm{in}}\\) 降到 \\((d_{\\mathrm{out}}+d_{\\mathrm{in}})r\\)。缺口是与 <a href="/llm/lora">LoRA</a> 划清：<strong>LoRA 冻结 \\(W_0\\)、学低秩更新；本课分解 \\(W_0\\) 本身。</strong> 后课把矩阵换成更高阶张量。不重导 GPTQ 的格子。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>截断 SVD 对 Frobenius 最优，却不是对层输出 \\(\\|WX-\\hat W X\\|\\) 最优。Hsu 等人的 FWSVD 用 Fisher / 梯度信息给行加权再分解，让重建对准损失敏感方向。激活感知的 SVD 同类：用校准 \\(X\\) 把「能量大的输入方向」留到前 \\(r\\) 个奇异成分里。问题与 AdaRound / GPTQ 平行——度量必须是任务几何，不是权重 MSE。</p><p>\\(r\\) 太小，一层的表达力掉到无法被残差补回，长链推理先死，短 PPL 后动。\\(r\\) 接近 \\(\\min(d_{\\mathrm{in}},d_{\\mathrm{out}})\\) 则不压缩。混精思想在这里变成混秩：敏感层留满秩，迟钝层狠压。</p><p><span class="marginnote">分解后两次 GEMM 是否加速，取决于 \\(r\\) 是否小到让 \\(UV\\) 的 FLOPs 低于原 \\(W\\)，以及核是否融合。只省参数、两次乘更慢，是常见失败。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>逐层：取 \\(W\\)，可选先按校准或 Fisher 加权，截断 SVD 得 \\(U\\Sigma V^\\top\\)，把 \\(\\Sigma\\) 吸进 \\(U\\) 或 \\(V\\)，存两个因子。可再短微调或 LoRA 修残差。与量化联合：先低秩再 <a href="/llm/gptq">GPTQ</a>，校准走 \\(UVx\\)。lm_head 与 embedding 往往更怕低秩，优先保护，与混精手工先验相同。</p>',9)),(e(),s(m,null,{default:r(()=>[h(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%BB%A1%E7%A7%A9%20W%22%5D%20--%3E%20MET%5B%22%E4%BB%BB%E5%8A%A1%E5%BA%A6%E9%87%8F%3A%20Fisher%20%E6%88%96%20WX%22%5D%0A%20%20MET%20--%3E%20SVD%5B%22%E6%88%AA%E6%96%AD%20SVD%22%5D%0A%20%20SVD%20--%3E%20UV%5B%22U%2C%20V%20%E5%9B%A0%E5%AD%90%22%5D%0A%20%20UV%20--%3E%20FUSE%7B%222r%20%EF%BC%9C%20min(d)%20%E4%B8%94%E6%9C%89%E6%A0%B8%3F%22%7D%0A%20%20FUSE%20--%3E%7C%E6%98%AF%7C%20FAST%5B%22%E4%B8%A4%E6%AC%A1%E7%98%A6%20GEMM%22%5D%0A%20%20FUSE%20--%3E%7C%E5%90%A6%7C%20MEM%5B%22%E5%8F%AA%E7%9C%81%E5%AD%98%E5%82%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要把 QLoRA 的 NF4 基座再做一遍 SVD 当「双压缩」而不重测：量化噪声改变奇异谱，秩的最优点会移。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(W\\) 的有效秩低，当输出主要落在少数输入方向上——校准域越窄，看起来越低秩，换域越崩。这是校准过拟合的低秩版。加权 SVD 把损失 Hessian 的主轴对齐到前 \\(r\\) 个成分，换的是域内 PPL，不是普遍可逆压缩。</p><p>与 LoRA 同时存在时：推理若合并 \\(W_0+BA\\) 再 SVD，秩预算要覆盖适配器撑开的方向；若保持 \\(UV+BA\\)，三因子，实现复杂，通常先合并再压。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要对每一层同一 \\(r\\)。不要在 \\(r\\) 不够小时指望继续预训练像 Sheared 那样愈合——低秩约束还在，愈合天花板更低。下一课张量分解：把 \\(W\\) 看成更高阶，秩的概念换成 TT/Tucker 秩，核更差。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>低秩分解压 \\(W_0\\)；LoRA 压 \\(\\Delta W\\)。检查点语义不同。</li><li>截断应对准 \\(WX\\) 或 Fisher，而不是 \\(\\|W-\\hat W\\|\\)。</li><li>两次 GEMM 只有在 \\(r\\) 足够小且实现融合时才加速。</li><li>敏感层混秩，头与 embed 优先保护。</li><li>出处：Hsu et al., ICLR 2022；Eckart–Young 作为 SVD 基线。</li></ul>',8))])}const f=i(A,[["render",p]]);export{D as __pageData,f as default};
